            var solution=PuzzleSolver.Solve(Model.Export());var m=solution.Moves[0];Tap("Bottle "+(m.Source+1));Tap("Bottle "+(m.Target+1));yield return new WaitForSecondsRealtime(1.1f);Check(Model.Moves==2,"Gösteri sonrası oyuncu normal aktarım yapabiliyor");Tap("Undo");Check(Model.Moves==1&&GameplayProgress.Current.Remaining(BoosterKind.Undo)==2,"Undo normal gerçek hakkıyla çalışıyor");Tap("Restart");Check(Model.Moves==0&&!Guide.Visible,"Restart örnek hamleyi sıfırlar; eğitim tekrar zorla açılmaz");
